// AWI: diagnosa sementara (hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/diag', array(
		'methods' => 'GET',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$out = array();
			foreach (array('bydjkt', 'Bunga 0%', 'unga 0') as $n) {
				$like = '%' . $wpdb->esc_like($n) . '%';
				$out[$n]['posts'] = $wpdb->get_results($wpdb->prepare("SELECT ID, post_type, post_status, post_title, LENGTH(post_content) len FROM {$wpdb->posts} WHERE post_content LIKE %s AND post_type NOT IN ('revision') LIMIT 40", $like));
				$out[$n]['meta'] = $wpdb->get_results($wpdb->prepare("SELECT post_id, meta_key, LENGTH(meta_value) len FROM {$wpdb->postmeta} WHERE meta_value LIKE %s LIMIT 40", $like));
				$out[$n]['opts'] = $wpdb->get_results($wpdb->prepare("SELECT option_name, LENGTH(option_value) len FROM {$wpdb->options} WHERE option_value LIKE %s LIMIT 40", $like));
			}
			foreach ($out['bydjkt']['posts'] as $p) {
				$c = get_post_field('post_content', $p->ID);
				preg_match_all('#.{0,160}bydjkt.{0,120}#s', $c, $m);
				$out['ctx'][$p->ID] = array_slice($m[0], 0, 4);
			}
			foreach ($out['Bunga 0%']['posts'] as $p) {
				$c = get_post_field('post_content', $p->ID);
				preg_match_all('#.{0,100}Bunga 0%.{0,60}#s', $c, $m);
				$out['ctxb'][$p->ID] = array_slice($m[0], 0, 6);
			}
			$up = wp_upload_dir();
			foreach (glob($up['basedir'] . '/wpforms/themes/*') ?: array() as $f) {
				$out['themefiles'][basename($f)] = is_file($f) ? substr_count(file_get_contents($f), 'bydjkt') : 'dir';
			}
			return $out;
		},
	));
});
